common:
float outline(vec2 p) {
  float a = atan(p.y, p.x) - iTime * turn;
  float r = size * (1.0 + breathe * sin(iTime * 1.3)) * (1.0 + 0.12 * cos(3.0 * a));
  return 1.0 - smoothstep(0.003, 0.009, abs(length(p) - r));
}

passes.fragment:
float over(float v, float edge) {
  return clamp((v - edge) * 400.0, 0.0, 1.0);
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float v = texture2D(iChannel0, uv).r;
  vec3 col = mix(background, deep, over(v, 0.05));
  col = mix(col, mid, over(v, 0.3));
  col = mix(col, bright, over(v, 0.6));
  gl_FragColor = vec4(mix(col, line, outline(p)), 1.0);
}
